    // --- I sei quadri della lezione dell'eclittica ---------------------
    'lezione.alto.breve': 'From above',
    'lezione.alto.titolo': 'From above it looks like a target',
    'lezione.alto.testo': 'Seen from over the Sun’s head the Solar System looks like a target: near-perfect circles, all travelled in the same direction, as though someone had drawn them with a compass. It is the picture we all carry in our heads — and it is also the one that hides the most important fact, because seen from above, something flat and something thick look identical.',
    'lezione.taglio.breve': 'Edge-on',
    'lezione.taglio.titolo': 'Turned edge-on: it is not a ball, it is a disc',
    'lezione.taglio.testo': 'Now the same scene drops until we see it in profile, and the circles flatten onto one another. Here is the fact: the planets are not scattered in every direction around the Sun, they all sit inside a thin plate. Each travels on a slightly different plane, but “slightly” means a few degrees.',
    'lezione.piano.breve': 'The plane',
    'lezione.piano.titolo': 'The floor of the Solar System',
    'lezione.piano.testo': 'To measure those degrees you need a floor to count them from, and the choice is natural: the plane of the Earth’s orbit, that is, ours. Extend it to infinity, out to the stars: the circle it traces in the sky is <strong>the ecliptic</strong>. The other orbits cross it barely tilted — Mercury 7.0°, Venus 3.4°, Saturn 2.5°, Mars 1.8°, Jupiter 1.3° — and that is why they always stay close to it.',
    'lezione.daQui.breve': 'From here',
    'lezione.daQui.titolo': 'How we see it from inside',
    'lezione.daQui.testo': 'We sit inside that floor and look at it edge-on: that is why the Sun, the Moon and the planets seem strung along the same line, crossing the sky from one horizon to the other. It is exactly the line the planetarium’s “Ecliptic” button switches on. These are the real planets of right now: the vertical scale is stretched six times, otherwise those two or three degrees would not show.',
    'lezione.analemma.breve': 'The analemma',
    'lezione.analemma.titolo': 'The ecliptic watched always at the same hour',
    'lezione.analemma.testo': 'Try going out every day at the same hour and marking where the Sun is. You do not get a point — nor a line: you get a <strong>stretched figure of eight</strong>, the analemma. The two causes are the same as before, taken one at a time. The Earth’s axis is tilted by 23.4°, and this raises and lowers the Sun by 47° between the two solstices: that is the height of the eight. The orbit is an ellipse, so in winter the Earth runs faster and the Sun reaches noon early or late by up to a quarter of an hour: that is the width. On the map you will find it switched on together with the ecliptic, in pale gold, and it passes exactly through where the Sun is right now.',
    'lezione.nome.breve': 'The name',
    'lezione.nome.titolo': 'Why it is called the “ecliptic”',
    'lezione.nome.testo': 'The name comes from eclipses. The Moon orbits on a plane tilted 5° to ours, so it touches the ecliptic at just two points: the <strong>nodes</strong>. For an eclipse you need two coincidences at once — the Moon at a node, and the Sun in the same direction (solar eclipse) or the opposite one (lunar eclipse). Watch the Sun go round: only twice a year does it line up with the nodes, and that is when the eclipse seasons open. That is why we do not get one a month. The tilt of the lunar orbit here is drawn four times stronger than the real thing: at exactly 5° it would be indistinguishable from the thickness of the line.',

    // --- Le fasi lunari ------------------------------------------------
    'fase.0.titolo': 'New Moon',
    'fase.0.spiegazione': 'The Moon sits between the Earth and the Sun. The face turned towards us is in shadow: a dark sky, excellent for deep-sky observing.',
    'fase.0.cosaPortare': 'A telescope for galaxies and nebulae, since the sky is very dark.',
    'fase.0.doveVederlo': 'Go far from the city to make the most of the total darkness.',
    'fase.0.comeVederlo': 'Use a star map to find your way in the dark.',
    'fase.1.titolo': 'First Quarter Moon',
    'fase.1.spiegazione': 'Half the lunar disc is lit. This is the best time to observe the craters along the terminator, where the shadows are long and sharp.',
    'fase.1.cosaPortare': 'Binoculars or a small telescope for the craters.',
    'fase.1.doveVederlo': 'Visible in the evening, high in the sky after sunset.',
    'fase.1.comeVederlo': 'Look at the light/shadow boundary: that is where the detail stands out.',
    'fase.2.titolo': 'Full Moon',
    'fase.2.spiegazione': 'The Earth sits between the Sun and the Moon. The lunar disc is fully lit and brilliant.',
    'fase.2.cosaPortare': 'Binoculars for the lunar seas; a moon filter helps against the intense light.',
    'fase.2.doveVederlo': 'Anywhere the sky is clear towards the horizon.',
    'fase.2.comeVederlo': 'To the naked eye the light is intense: a moon filter makes observing more comfortable.',
    'fase.3.titolo': 'Last Quarter Moon',
    'fase.3.spiegazione': 'The other half of the lunar disc is lit. It rises deep in the night and is visible in the early morning.',
