    // --- The «Tonight» panel of the dashboard ---------------------------
    'stanotte.mancaPosizione': 'Your position is missing',
    'stanotte.mancaPosizioneTesto': 'Without a point on the Earth I cannot tell you when it gets dark, what rises and what sets. There are three ways to give it to me — GPS, your connection, or your town picked from a list — and at least one always works. It is stored on this device only.',
    'stanotte.buioAstronomico': 'Astronomical darkness',
    'stanotte.nienteBuio': 'no full darkness tonight',
    'stanotte.tramontoAlba': 'Sunset {tramonto} · sunrise {alba}',
    'stanotte.crepuscoloTuttaNotte': 'The Sun never gets down to \u221218°: twilight all night long. Sunset {tramonto}.',
    'stanotte.nonCalcolabile': 'cannot be worked out',
    'stanotte.latitudiniAlte': 'At your latitude the Sun may not set at all.',
    'stanotte.lunaOrari': 'Rises {sorge} · sets {tramonta}.',
    'stanotte.disturbo.alto': 'sky much brighter: better the Moon and the planets than faint objects',
    'stanotte.disturbo.medio': 'moderate interference for faint objects',
    'stanotte.disturbo.basso': 'dark sky: excellent for meteors and deep sky',
    'stanotte.datiNonDisponibili': 'data unavailable',
    'stanotte.senzaLibreriaOrbitale': 'Orbital library not loaded: reopen the app while you have a connection, and then it will work offline too.',
    'stazione.passaggio': 'Sky at {quando}: {nome} is towards {dove}, {alt}° above the horizon. The map follows it on its own — drag the sky to let go.',
    'stazione.adesso': '{nome} is towards {dove} right now, {alt}° above the horizon. The map follows it on its own — drag the sky to let go.',
    'stazione.sottoOrizzonte': '{nome} is below the horizon right now, towards {dove} at {alt}°: the map points at it anyway, under the skyline.',
    'stazione.senzaDati': 'Downloading the orbital data for {nome}: as soon as it arrives the map will point straight at it.',
    'eventoStazione.titolo': 'Visible pass of {nome}',
    'eventoStazione.spiegazione': '{nome} passes in sunlight while the sky here is dark: it culminates at {altezza}° towards {direzione} and remains observable for about {durata} min.',
    'eventoStazione.cosaPortare': 'No instrument is needed: it is easy to see with the naked eye.',
    'eventoStazione.doveVederlo': 'It appears at {inizio} towards {direzioneInizio}, culminates at {culmine} towards {direzioneCulmine}, and disappears at {fine} towards {direzioneFine}.',
    'eventoStazione.comeVederlo': 'Go outside a few minutes early and look for a star-like light moving steadily without blinking.',
    'eventoStazione.giudizio': 'Clearly visible: sunlit, {altezza}° above the horizon towards {direzione}.',
    'faseLuna.nuova': 'New Moon',
    'faseLuna.crescente': 'Waxing crescent',
    'faseLuna.primoQuarto': 'First Quarter',
    'faseLuna.gibbosaCrescente': 'Waxing gibbous',
    'faseLuna.piena': 'Full Moon',
    'faseLuna.gibbosaCalante': 'Waning gibbous',
    'faseLuna.ultimoQuarto': 'Last Quarter',
    'faseLuna.calante': 'Waning crescent',

    // --- Il blocco «Da qui» delle schede dell'agenda -------------------
    'locale.servePosizione': 'With your location I can tell you whether this event is visible from your home, at what time and in which direction.',
    'locale.sorgeTramonta': 'Rises {sorge} · sets {tramonta}',
    'locale.buioAstronomico': 'Astronomical darkness that night: {da} → {a}',
    'locale.osservabilita': 'Observability {punti}/100',
    'locale.momentoConsigliato': 'Recommended moment: {quando}',
    'locale.sottoMaRecupera': 'At the peak it is below the horizon from here, but the same night it reaches {gradi}° around {ora}.',
    'locale.nonVisibile': 'Not visible from here: at the moment of the event the object is below the horizon.',
    'locale.cieloAncoraChiaro': 'At the exact time of the event the sky is still bright (Sun at {sole}°)',
    'locale.guardaloVersoLe': ': look for it around {ora}, when it is {gradi}° high towards {dove}.',
    'locale.cercaNelBuio': '. Look for the object in the nearest hours of darkness.',
    'locale.bassaSullOrizzonte': 'Visible but low on the horizon ({gradi}°): you need a clear view towards {dove}.',
    'locale.benVisibile': 'Clearly visible from here: {gradi}° above the horizon, towards {dove}.',

    // --- I consigli di astrofotografia ---------------------------------
    'foto.base.treppiede': 'A tripod (even a small one) makes more difference than any expensive lens.',
    'foto.base.telefono': 'With a phone: Pro or Night mode, a 3-second self-timer so you do not shake it, manual focus at ∞.',
    'foto.luna.titolo': 'Photographing the Moon',
    'foto.luna.obiettivo': 'The longest you have: 200–300 mm on a DSLR, optical zoom on a phone.',
    'foto.luna.esposizione': 'The “looney” rule: 1/125 s, f/8, ISO 100. The Moon is lit by the Sun, so treat it as a daytime subject.',
    'foto.luna.errore': 'The classic mistake is overexposing: if you get a white disc with no craters, cut 2–3 stops.',
    'foto.eclissi.titolo': 'Photographing the eclipse',
    'foto.eclissi.obiettivo': 'A 200 mm telephoto or longer. For a solar eclipse you need a certified solar filter in front of the lens.',
    'foto.eclissi.esposizione': 'Lunar eclipse: ISO 800, f/5.6, 1/4 s during totality (the red Moon is far darker). Partial solar eclipse: like a daytime photo, but only with a filter.',
    'foto.eclissi.errore': 'Never point at the Sun without a filter: you will burn the sensor and, if you look through the viewfinder, your eye too.',
    'foto.meteore.titolo': 'Photographing shooting stars',
    'foto.meteore.obiettivo': 'A fast wide-angle (14–24 mm, f/2.8 or faster): you need field, not magnification.',
    'foto.meteore.esposizione': 'ISO 1600–3200, f/2.8, 15–20 s frames back to back for hours. The 500 rule: maximum seconds = 500 ÷ focal length; beyond that the stars become dashes.',
    'foto.meteore.errore': 'You do not chase the meteor: you aim the camera at a patch of sky ~40° from the radiant and shoot continuously.',
    'foto.pianeti.titolo': 'Photographing planets and conjunctions',
    'foto.pianeti.obiettivo': 'For a conjunction a 50–100 mm is enough: what makes the picture is the landscape with the two bodies close together.',
    'foto.pianeti.esposizione': 'ISO 400–800, f/4, 1–2 s if they are still in twilight. Planets are bright: better to underexpose.',
    'foto.pianeti.errore': 'Include a tree or a roofline: a photo of two dots in the black tells no story.',
    'foto.cielo.titolo': 'Photographing the sky',
    'foto.cielo.obiettivo': 'A fast wide-angle and manual focus on a bright star.',
    'foto.cielo.esposizione': 'ISO 1600, f/2.8, 10–20 s. Shoot RAW if you can: you recover a lot in post.',
    'foto.cielo.errore': 'Avoid digital zoom: it ruins the detail without adding anything.',

