    'tel.tipo.newton': 'Newtonian (reflector)',
    'tel.tipo.rifrattore': 'Refractor',
    'tel.tipo.catadiottrico': 'Maksutov / Schmidt-Cassegrain',
    'tel.cercatore.reddot': 'Red dot',
    'tel.cercatore.ottico': '6×30 finder',
    'tel.cercatore.ottico9': '9×50 finder',
    'tel.cercatore.nessuno': 'No finder',
    'tel.cielo.2': 'Mountain sky',
    'tel.cielo.2.nota': 'The best conditions you will find without leaving the country.',
    'tel.cielo.3': 'Dark countryside',
    'tel.cielo.3.nota': 'Structured Milky Way: this is where deep sky opens up.',
    'tel.cielo.4': 'Suburbs / nearby countryside',
    'tel.cielo.4.nota': 'Milky Way visible but washed out.',
    'tel.cielo.5': 'Bright suburbs',
    'tel.cielo.5.nota': 'Milky Way barely hinted at near the zenith.',
    'tel.cielo.6': 'Small-town sky',
    'tel.cielo.6.nota': 'Milky Way invisible, a bright glow along the horizon.',
    'tel.cielo.8': 'City',
    'tel.cielo.8.nota': 'Only a few dozen stars show: planets and the Moon stay excellent.',

    'tel.profondo.M31.aspetto': 'A milky oval as wide as three Moons in a row. The core is sharp, the arms are not: those stay in the photographs.',
    'tel.profondo.M42.aspetto': 'The one nebula that really shows a shape: two wings of grey-green gas around four little stars in a square (the Trapezium).',
    'tel.profondo.M45.aspetto': 'Too large for the telescope: it only fits in the finder or in binoculars. Blue stars, razor sharp.',
    'tel.profondo.M44.aspetto': 'Forty-odd stars, scattered and wide. Here too the widest eyepiece is the right one.',
    'tel.profondo.M13.aspetto': 'A grainy ball of light: at 100× the edges start breaking into single stars. It is the finest sight of the summer sky.',
    'tel.profondo.M8.aspetto': 'An elongated grey patch cut by a dark lane, with a star cluster laid on top of it.',
    'tel.profondo.M22.aspetto': 'Wider and better resolved than M13, but it sits low: the horizon haze eats half of it.',
    'tel.profondo.Doppio.aspetto': 'Two fistfuls of stars in the same field, close together. You need the widest eyepiece to get both at once.',
    'tel.profondo.M57.aspetto': 'A tiny grey doughnut, but unmistakable. It takes magnification well: this is where the 4 mm makes sense.',
    'tel.profondo.M27.aspetto': 'A bright grey-green apple core. Among the nebulae it is the easiest one after M42.',
    'tel.profondo.M51.aspetto': 'Two small round patches side by side. The bridge of material joining them, so obvious in photographs, is simply not there at the eyepiece.',
    'tel.profondo.M81.aspetto': 'A sharp, bright oval; in the same field M82, which is a thin spindle instead. Two galaxies in one go.',
    'tel.profondo.M15.aspetto': 'A compact ball with a strongly concentrated centre: it looks like a comet without a tail.',
    'tel.profondo.M3.aspetto': 'A first-rate globular, almost as good as M13: it starts resolving around 120×.',
    'tel.pianeta.Moon.aspetto': 'Along the terminator (the boundary between light and shadow) the craters cast long shadows and look three-dimensional. That is where you look, not at the full part.',
    'tel.pianeta.Mercury.aspetto': 'A tiny disc with a phase, like a miniature Moon. Always low, always shimmering.',
    'tel.pianeta.Venus.aspetto': 'Dazzling and completely featureless: no detail, only the phase. Beautiful as a crescent, just before sunset.',
    'tel.pianeta.Mars.aspetto': 'Small and orange. Only near oppositions does it show the white polar cap and a few dark markings.',
    'tel.pianeta.Jupiter.aspetto': 'Two dark belts cross the disc, and four dots in a line change places every evening: those are the Galilean moons.',
    'tel.pianeta.Saturn.aspetto': 'The ring shows at 50× already, separated from the disc by 120×. It is the object that convinces anyone who looks.',
    'tel.pianeta.Uranus.aspetto': 'A greenish disc barely larger than a star: the satisfaction is in recognising it, not in the detail.',
    'tel.pianeta.Neptune.aspetto': 'Indistinguishable from a star except for the bluish colour. You need the map to be sure you have found it.',

