    'did.spa.soleCasa': 'the Sun — home',
    'did.spa.soleQui': 'the Sun — we are here',
    'did.spa.seiQui': 'you are here',
    'did.spa.seiQuiMeta': 'you are here — {nome}',
    'did.spa.seiQuiAl': 'you are here · {al} ly',
    'did.spa.raggioAl': '{al} ly',
    'did.spa.giraFigura': 'Turn it with your finger: the figure is a coincidence, and it shows at once',
    'did.spa.giraVentaglio': 'Turn it with your finger: from there the sight lines fan out',
    'did.spa.giraPoiSpostati': 'Turn it with your finger — then move away, and watch what happens to the sight lines',
    'did.spa.sulSole': 'You are on the Sun: it is the figure as ever',
    'did.spa.daPianetaDi': 'From a planet of {nome} · {al} light years from home',
