    'did.spa.letturaCoppia': 'The pair that opened up the most',
    'did.spa.nota': 'The distances come from the Hipparcos parallaxes (HYG database). For a dozen very distant stars the parallax is not enough to give a number: those are marked with a question mark, and placed at the median distance of their figure. The magnitudes in the third panel are recomputed from the true distance: moving away changes not only the drawing but also which stars are still visible. Going to stand on a star of the figure, that one disappears from the sky — it is the Sun of that place — and the others rearrange themselves from scratch: the dashed grey is how they stood seen from here.',
    'did.spa.pontePlanetario': 'See it in the planetarium',
