    'did.tram.kmAria': '{km} km of air against the 8.4 that would do with the Sun overhead: {x} times as much.',
    'did.tram.soleSottoOrizzonte': 'The Sun is below the horizon: the light that is left has crossed all of this and more.',
    'did.tram.everest': 'Eight and a half kilometres is a little more than Everest (8.8) and less than an airliner (11).',
    'did.tram.stessoMetro': 'Curvature, thickness and path at the same scale — nothing exaggerated.',
    'did.tram.rifrazione': 'refraction {n}′',
    'did.tram.dovEDavvero': 'where the Sun really is',
    'did.tram.discoSchiacciato': 'Disc flattened by {pct}% · refraction {r}′ against the 32′ of its diameter',
    'did.tram.discoSotto': 'The disc is below the horizon: twilight is what is left',
    'did.tram.campoInquadrato': 'Field shown: {gradi}° in height — the Sun is at its true size',
    'did.tram.tuttaLaLuce': 'all the light (100%)',
    'did.tram.quantaLuce': 'How much light reaches the eye, after {n} air masses',
    'did.tram.coloreCheNeEsce': 'the colour that comes out',
    'did.tram.cieloTinta': '{tinta} sky',
    'did.tram.sottoTerra': 'molecules far smaller than the light: Rayleigh, λ⁻⁴',
    'did.tram.sottoMarte': 'dust as big as the light, and iron that eats the blue',
    'did.tram.giornoCorto': 'By day: we are blue, Mars is straw-coloured.',
    'did.tram.giornoLungo': 'By day: here the blue is scattered across the whole sky, on Mars the dust eats it and leaves the colour of sand.',
    'did.tram.tramontoCorto': 'At sunset they swap: we go red, Mars goes blue.',
    'did.tram.tramontoLungo': 'At sunset they swap: our sky turns red, and on Mars the blue gathers around the Sun instead of scattering.',
    'did.tram.otticoCorto': 'Molecules: Earth 0.097, Mars 0.006. Dust: 0.5.',
    'did.tram.otticoLungo': 'Optical depth at 550 nm — molecules: Earth 0.097, Mars 0.006 (sixteen times less). Martian dust: 0.5, that is eighty times its own air.',
    'did.tram.trascinaCorto': 'Drag up and down to move the Sun.',
    'did.tram.trascinaLungo': 'Drag up and down to move the Sun — it moves in both skies.',
    'did.tram.tinta.quasiNero': 'almost black',
    'did.tram.tinta.grigio': 'grey',
    'did.tram.tinta.azzurro': 'light blue',
    'did.tram.tinta.blu': 'blue',
    'did.tram.tinta.paglia': 'straw-coloured',
    'did.tram.tinta.ocra': 'ochre yellow',
    'did.tram.tinta.arancione': 'orange',
    'did.tram.tinta.rosso': 'red',
    'did.tram.tinta.verdastro': 'greenish',
    'did.tram.oraGirata': '{ora} — turned by {gradi}°',
    'did.tram.sullOrizzonte': 'exactly on the horizon',
    'did.tram.sopraOrizzonte': '{gradi}° above the horizon',
    'did.tram.sottoOrizzonte': '{gradi}° below the horizon',
    'did.tram.tramontatoSotto': 'set, {gradi}° below',
    'did.tram.alzatoDiTanto': '{n}′ — that is how much the Sun is lifted',
    'did.tram.massaAria': '{x}× · {km} km of air',
    'did.tram.piuDebole': '{pct}% — {volte}× fainter',
    'did.tram.col.rossoPuro': 'pure red',
    'did.tram.col.bianco': 'neutral white',
    'did.tram.col.giallo': 'yellow',
    'did.tram.col.dorato': 'golden orange',
    'did.tram.col.profondo': 'deep orange',
    'did.tram.letturaBarra': '{ora} · Sun at {gradi}°',
    'did.tram.dalParallelo': 'You are looking from latitude <strong>{lat}° {emiLat}</strong>. Today the Sun is overhead at latitude <strong>{decl}° {emiDecl}</strong>,',
    'did.tram.nonSorge': 'so from here it does not rise at all: it goes round all day below the horizon.',
    'did.tram.nonSaleSopra': 'so from here it never climbs above <strong>{gradi}°</strong>. The time is true solar time: noon is when the Sun crosses the meridian.',
    'did.tram.spiegaCrepuscolo': 'The disc has vanished below the optical horizon. What is left in the sky is <strong>twilight</strong>: light that no longer arrives straight, but scattered by the high air that from up there still sees the Sun. It is the same orange ring that, on the globe, is seen edge-on from space.',
    'did.tram.spiegaRifrazione': 'Geometrically the Sun is already <strong>{gradi}° below the horizon</strong>: without an atmosphere it would have set. We still see it because the air bends the ray by <strong>{primi}′</strong> — more than the half degree the disc itself measures, and that is why the "true" sunset and the one you watch are not the same instant.',
    'did.tram.spiegaAria': 'The light crosses <strong>{km} km</strong> of air instead of the 8.4 that would do with the Sun straight overhead: <strong>{x} times</strong> as much. Rayleigh scattering grows as λ⁻⁴, so the blue goes first — <strong>{blu}%</strong> of it is left — while <strong>{rosso}%</strong> of the red still gets through. The blue that is lost has not vanished: it is the colour of the sky around you.',
    'did.tram.targaGlobo': '<strong>Drag the Earth</strong> to turn it. The Sun stands still.',
    'did.tram.guardaIlGlobo': 'View the globe:',
    'did.tram.notaGesto': 'One finger sideways turns the Earth — that is, makes the hours pass — and up or down raises and lowers the viewpoint; two fingers zoom in.',
    'did.tram.targaAria': '<strong>Drag the Sun</strong> — true scale, curvature included. The vertical tick is the shortest possible path: <em>the long one fits inside it as many times as the air mass says</em>.',
    'did.tram.targaCielo': '<strong>Drag the Sun up and down.</strong> The disc is at its true size, flattened by refraction, and beside it is where it would be without air',
    'did.tram.targaBande': 'How much light is left, colour by colour',
    'did.tram.targaMarte': 'Same hour, same scale: all that changes is <em>what</em> scatters the light.',
    'did.tram.notaMarte': 'Here the scattering is done by air molecules, a thousand times smaller than the wavelength: it is the <strong>Rayleigh</strong> regime, where scattering grows as λ⁻⁴ and goes more or less in all directions. The blue is spread across the whole sky — and from whichever way you look, some of it arrives: <strong>a blue sky</strong>. On Mars the air is 0.6% of ours and nothing is left of Rayleigh: the scattering is done by <strong>dust</strong>, grains a couple of microns across, that is <em>as big as</em> the wavelength. Dust like that does not look at colour when it stops the light, but re-scatters it with a forward peak that is narrower the shorter the wave — and on top of that it is iron oxide, which eats the blue. Far from the Sun absorption wins (<strong>a straw-coloured sky</strong>), near the Sun the forward peak wins (<strong>a blue halo at sunset</strong>). It is our sky exactly the other way round.',
    'did.tram.etichettaSlitta': 'How far the Earth has turned since noon',
