    'missione.curiosita.lira.3': 'The technical details help you find it; the memorable part begins now, when a point on a chart becomes real light in your eyes.',
    'missione.curiosita.cigno.1': 'A story lives in this light: look at its colour and shape before thinking about numbers. Astronomy begins with noticing.',
    'missione.curiosita.cigno.2': 'People watched this same part of the sky long before telescopes, turning seasons, journeys and wonder into stories.',
    'missione.curiosita.cigno.3': 'The technical details help you find it; the memorable part begins now, when a point on a chart becomes real light in your eyes.',
    'missione.curiosita.scorpione.1': 'A story lives in this light: look at its colour and shape before thinking about numbers. Astronomy begins with noticing.',
    'missione.curiosita.scorpione.2': 'People watched this same part of the sky long before telescopes, turning seasons, journeys and wonder into stories.',
    'missione.curiosita.scorpione.3': 'The technical details help you find it; the memorable part begins now, when a point on a chart becomes real light in your eyes.',
    'missione.curiosita.iss.1': 'The ISS is 109 metres long, about the size of a football field, and travels at roughly 28,000 kilometres per hour.',
    'missione.curiosita.iss.2': 'The International Space Station has been continuously inhabited since November 2000: while you watch it, somebody aboard is working.',
    'missione.curiosita.iss.3': 'Its broad solar arrays reflect sunlight, which is why the ISS can become brighter than every star.',
    'missione.curiosita.tiangong.1': 'Tiangong means “Heavenly Palace”: its three modules form a T while orbiting Earth.',
    'missione.curiosita.tiangong.2': 'It is both a crewed station and a laboratory, where astronauts carry out experiments in weightlessness.',
    'missione.curiosita.tiangong.3': 'Tiangong circles Earth in about 92 minutes and sees sixteen sunrises and sunsets each day.',
    'missione.curiosita.stazione.1': 'That light is a home in free fall, moving at about 28,000 kilometres per hour and continually missing Earth. Unlike an aircraft, reflected sunlight makes it shine steadily.',
    'missione.curiosita.stazione.2': 'Astronauts aboard see roughly sixteen sunrises and sunsets each day. The crossing dot carries people who may be looking back through a window right now.',
    'missione.curiosita.stazione.3': 'Space stations are assembled piece by piece while already in flight. Their shine comes from solar arrays and modules launched over many different years.',
    'missione.curiosita.profondo.1': 'This light shows the object not as it is now, but as it was when the light left. Looking far away is nature’s own time machine.',
    'missione.curiosita.profondo.2': 'Many faint objects carry an M because Charles Messier catalogued them to avoid mistaking them for comets. A list of nuisances became a map of wonders.',
    'missione.curiosita.profondo.3': 'Rest your gaze just beside it: peripheral vision catches dim light better. The object may appear precisely when you stop staring at it.',
    'missione.curiosita.costellazione.1': 'This figure is not one object in space: its stars may be vastly different distances away. The drawing exists only from Earth.',
    'missione.curiosita.costellazione.2': 'Before books, the sky was a library. Figures like this preserved seasons, routes, animals and adventures; remembering a story could mean remembering when to sow or where to sail.',
    'missione.curiosita.costellazione.3': 'Official constellation borders were fixed in the twentieth century, but their figures are far older. Modern geometry and ancient imagination share this sky.',
    'missione.curiosita.stella.1': 'Its colour is a thermometer: blue means hotter, orange cooler. Even in a single point of light, your eye can read another sun’s temperature.',
    'missione.curiosita.stella.2': 'For most of history stars were ancestors, heroes or distant fires. Knowing they are suns does not erase those stories; it adds staggering distance to them.',
    'missione.curiosita.stella.3': 'The light you see left this star years or centuries ago. It crossed empty space to end its journey, for an instant, on your retina.',
    'missione.curiosita.pianeta.1': 'Watch whether it twinkles: a planet usually shines more steadily than a star because its tiny disc averages atmospheric ripples. It is a useful trick for recognising a world.',
    'missione.curiosita.pianeta.2': 'Planet means “wanderer”. Ancient observers saw these lights disobey the fixed star patterns and told stories of gods to explain their journeys.',
    'missione.curiosita.pianeta.3': 'You are seeing sunlight reflected by another world: ordinary daylight travelled out, bounced, and returned to your eyes carrying news of a cosmic neighbour.',
    'missione.curiosita.generica.1': 'A story lives in this light: look at its colour and shape before thinking about numbers. Astronomy begins with noticing.',
    'missione.curiosita.generica.2': 'People watched this same part of the sky long before telescopes, turning seasons, journeys and wonder into stories.',
    'missione.curiosita.generica.3': 'The technical details help you find it; the memorable part begins now, when a point on a chart becomes real light in your eyes.',
    'missione.curiosita.luna': 'Astronaut footprints could remain intact for millions of years: the Moon has no wind or rain to erase them.',
    'missione.curiosita.giove': 'The Great Red Spot is a storm wider than Earth and has been watched for centuries, although it is now slowly shrinking.',
    'missione.curiosita.saturno': 'The rings look solid, but are countless pieces of ice, from dust-sized grains to chunks as large as a house.',
    'missione.curiosita.sirio': 'Sirius has a tiny, extraordinarily dense companion: a teaspoon of that white dwarf’s material would weigh several tonnes on Earth.',
    'missione.curiosita.pleiadi': 'The Pleiades are young stars born together. Almost every culture turned them into a story, from the Greek Seven Sisters to Māori traditions.',
    'missione.curiosita.stazione': 'Space stations race at roughly 28,000 kilometres per hour and cross the sky without blinking because they continuously reflect sunlight.',
    'missione.curiosita.profondo': 'That light travelled through space for years, centuries, or millions of years: observing it truly means looking into the past.',
    'missione.curiosita.costellazione': 'The stars in the figure only look close through perspective; in space they can be hundreds of light-years apart.',
    'missione.curiosita.stella': 'Colour reveals temperature: blue stars are hotter than white ones, while orange and red stars have cooler surfaces.',
    'missione.curiosita.pianeta': 'Planets shine by reflected sunlight and usually twinkle less than stars because their tiny discs soften atmospheric turbulence.',
    'missione.curiosita.generica': 'The light reaching your eyes crossed space without shortcuts: at this moment you are witnessing an authentic cosmic history.',

