    'missione.aiuto1': 'Turn to face {dove} and look up: it is {altezza}, about {gradi}° above the horizon line.',
    'missione.aiuto2': 'Find {da} first, it is easy to spot. From there move {verso} by {misura}, {su}.',
    'missione.aiuto2senzaRiferimento': 'There is nothing bright next to it to use as a handhold: take the direction with the compass and raise your eyes slowly.',
    'missione.aiuto3': 'It may not be your fault: from there a house, a tree or a hill could be in the way. Try moving a few metres, or open the planetarium to see where it really is.',
