    'missione.curiosita.centroGalattico.2': 'In there sits Sagittarius A*, a black hole of four million solar masses. We know because for thirty years the orbits of the stars circling it have been tracked: one of them completes a lap in sixteen years, at a twentieth of the speed of light.',

    // --- L'atlante delle costellazioni (costellazioni.js) -------------
    'cost.figuraDiBuio': 'a figure made of darkness',
    'cost.nessunaConQuestoNome': 'No constellation by that name.',
    'cost.daQuiMai': 'never from here',
    'cost.nonTramontaMai': 'never sets',
    'cost.appenaSullOrizzonte': 'barely {gradi}° above the horizon',
    'cost.disegno': 'artwork',
    'cost.nonTrovata': 'Constellation not found.',
    'cost.cieloAustrale': 'southern sky',
    'cost.cieloBoreale': 'northern sky',
    'cost.cieloEquatoriale': 'equatorial sky',
    'cost.conDisegno': 'with artwork',
    'cost.maiVisibile': '<strong>It can never be seen from here.</strong> At your latitude ({lat}°) it stays entirely below the horizon, at any hour and in any month: it is not a matter of waiting for the right night, it is the curvature of the Earth. The button below takes you where it can be seen.',
    'cost.circumpolare': '<strong>From here it never sets:</strong> it circles the pole and stays above the horizon all night, all year. At best it reaches {gradi}° of altitude.',
    'cost.altezzaMassima': 'From here it reaches at most <strong>{gradi}°</strong> above the horizon{nota}.',
    'cost.bassaNota': ' — low, you need a clear horizon on that side',
    'cost.culminaVerso': 'It culminates at midnight around <strong>{mese}</strong>, and that is the month it is best seen in.',
    'cost.portamiDoveSiVede': 'Take me where it can be seen',
    'cost.portamiSottoIlCielo': 'Take me under its sky',
    'cost.doveStanno': 'Where they really are',
    'cost.doveStannoTitolo': 'Its stars placed in real space, each at its own distance: the figure is an effect of perspective, and from another planet it is not there',
    'cost.notaConDisegno': 'The lines are the official figure, the light stroke is the artwork: the same curves the planetarium lays over the real sky.',
    'cost.notaSenzaDisegno': 'For this figure the planetarium draws the official lines. There is no artwork: these are the figures nobody, not even the people who invented them, ever really managed to see.',
    'cost.servePosizione': 'To say where to look I need your position: open it from the Time and place panel.',
    'cost.cercaIlBuio': '{nome}: you are at {meta}. Look for the darkness, not the stars — the figure is the dark patch in the middle of the Milky Way.',
    'cost.scegliDallElenco': 'Choose a constellation from the list: you will find the figure, the artwork, who named it and whether it can be seen from your home.',

