    'ui.ho-visto': 'I saw it!',
    'ui.i-laghi-e-i-fiumi-veri-attorno-a-te': 'The real lakes and rivers around you, drawn where they are and at the distance they are: still water reflects the sky like a mirror, and the Moon lays its path of light across it. Only those not hidden behind a ridge are visible. They are downloaded from OpenStreetMap once and then stay available offline; how far to look for them is set in Settings',
    'ui.i-nomi-delle-montagne-che-spuntano-sopra-l': 'The names of the mountains that rise above the horizon, with their altitude, pinned to the real summit by a thread: only those actually visible from here are named, not the ones hidden behind a nearer ridge. They start switched off; once on they are downloaded once and the choice is remembered. How far to look for them is set in Settings',
    'ui.i-quadri-della-lezione': 'The panels of the lesson',
    'ui.ics-aiuto': 'Download an <code>.ics</code> file with the upcoming events: your phone’s calendar will take care of the reminders, even with the app closed.',
    'ui.il-cerchio-che-il-sole-percorre-in-un-anno': 'The circle the Sun travels through the stars in a year: the plane of the Earth’s orbit seen edge-on. The planets always stay within a few degrees of this line, and the plumb line measures how many. It stays on whichever object you pick, until you switch it off',
    'ui.il-cielo-a-tutto-schermo-con-i-comandi-in': 'The sky full screen, with the controls overlaid',
