    'ui.il-nord-punta-storto-bussola-e-posizione': 'Is north off? Compass and position',
    'ui.il-palazzo-di-fronte-la-collina-gli-alberi': 'The building opposite, the hill, the trees. Declare how high they are in degrees (a fist at arm’s length is about 10°) and from then on the app stops offering you things you will never see from home. Zero means a clear horizon.',
    'ui.il-percorso-del-cono-d-ombra-sulla-terra': 'The path of the shadow cone across the Earth',
    'ui.il-planetario-e-su-questo-istante': 'The planetarium is at this moment.',
    'ui.il-planetario-punta-il-telefono-verso-il': 'Planetarium: point your phone at the sky and see what is there',
