    'ui.l-istante-mostrato-tocca-per-data-e-passo': 'The moment shown: tap for the date and the time step',
    'ui.l-istante-mostrato-tocca-per-scrivere-una': 'The moment shown: tap to type a date',
    'ui.l-orizzonte-attorno-a-te': 'The horizon around you',
    'ui.l-orizzonte-prende-la-forma-vera-del-terreno': 'The horizon takes the real shape of the terrain around you: hills, mountains, sea, plain — each with its own colour. It is downloaded once and then stays available offline. Switched off, the terrain is not drawn. Zoom far enough into an object and the terrain turns transparent by itself, as in Stellarium',
    'ui.la-cartella-di-astrocalendario-non-e-ancora': 'The AstroCalendar folder is not connected yet',
    'ui.la-citta-in-elenco-o-le-coordinate-esatte': 'A town from the list, or the exact coordinates. Works offline and without permissions.',
    'ui.la-classifica-usa-le-strade-e-i-divieti-di': 'The ranking uses the roads and access restrictions present in OpenStreetMap, as well as altitude and terrain profile. The data may be incomplete: before setting off, check signage, whether you can stop, the weather and the safety of the place.',
    'ui.la-forma-vera-del-terreno-non-solo-la-sua': 'The real shape of the terrain, not just its outline: the valleys running down, the flanks of the hills, the cut of the river, drawn in strokes as on a panoramic plate. Around you the step is twenty-seven metres, against the three degrees of the banded profile. It is downloaded once per place (four to six tiles) and then stays available offline. Switched off, the banded profile returns',
    'ui.la-luna-entra-nell-ombra-della-terra-chi-la': 'The Moon enters the Earth’s shadow: everyone who can see it in the sky sees all of it, at the same moment',
    'ui.la-mappa-a-tutto-schermo-con-i-comandi-in': 'The map full screen, with the controls overlaid',
    'ui.la-mappa-non-e-disponibile-adesso-serve-la': 'The map is not available right now — it needs the network to load. The coordinates in the “From Google Maps” panel work all the same.',
    'ui.la-modalita-hover-e-disponibile-quando-la': 'Hover mode is available when the view follows the phone',
    'ui.la-posizione-resta-salvata-solo-su-questo': 'Your position stays saved on this device only: it is not sent to anyone, and the app uses it to do the maths locally.',
    'ui.la-scegli-tu': 'You choose it',
    'ui.la-strada-che-l-oggetto-scelto-percorre-nel': 'The path the chosen object travels across the sky in the hours around this moment: dashed where it has already been, solid where it is going, with the hour marked hour by hour',
    'ui.la-terra-e-la-luna-da-vicino-coi-due-coni-d': 'The Earth and the Moon close up, with their two shadow cones: this is where you see why an eclipse does not happen at every full Moon — the Moon’s orbit is tilted by 5.1°, and at that distance it means thirty-four thousand kilometres off target.',
    'ui.la-terra-sotto-di-te-terreno-rilievo-luci': 'The ground beneath you: terrain, relief, lights, water',
    'ui.la-tua-nota': 'Your note',
