    'ui.le-cupole-di-luce-dei-paesi-veri-attorno-a': 'The light domes of the real towns around you, with their names on the horizon: they tell you which way NOT to look for faint things. They are not visible by day',
    'ui.le-distanze-fra-le-orbite-sono-compresse-per': 'The distances between the orbits are compressed to fit them all on screen: Saturn really is twenty-five times farther than Mercury. The angles, which are what the lesson is about, are the true ones.',
