    'ui.sei-banchi-di-prova-con-dentro-le-posizioni': 'Six benches built around the real positions of the planets, to understand the six things behind everything else in the app: why the planets sometimes go backwards, which three rules govern every orbit, how you gain speed by passing close to a planet, why you can only set off for Mars every twenty-six months, when the planets really do line up, and how the Sun manages to light an aurora on the other side of the planet. Each bench ends with buttons that take the same thing into the planetarium and into the 3D Solar System.',
